func Normalize(out *Classification) *Classification {
	if out == nil {
		return FallbackSafe()
	}

	out.Category = strings.ToLower(strings.TrimSpace(out.Category))
	if out.Category == "" {
		out.Category = "safe"
	}

	out.SuggestedAction = strings.ToLower(strings.TrimSpace(out.SuggestedAction))
	if out.SuggestedAction == "" {
		out.SuggestedAction = "none"
	}

	if out.Confidence < 0 {
		out.Confidence = 0
	}
	if out.Confidence > 1 {
		out.Confidence = 1
	}

	if out.Severity < 0 {
		out.Severity = 0
	}
	if out.Severity > 100 {
		out.Severity = 100
	}

	out.Reason = strings.TrimSpace(out.Reason)
	if len(out.Reason) > 200 {
		out.Reason = out.Reason[:200]
	}

	return out
}

func (c *Classification) IsHarmful(threshold int) bool {
	if c == nil {
		return false
	}
	return c.Category != "safe" && c.Severity >= threshold && c.Confidence >= 0.6
}

func (c *Classification) IsCritical() bool {
	return c != nil && c.Severity >= 85 && c.Confidence >= 0.75
}

func (c *Classification) ShouldNotify() bool {
	if c == nil {
		return false
	}
	switch c.Category {
	case "hate", "violence", "selfharm", "phishing", "raid":
		return c.Severity >= 40
	default:
		return c.Severity >= 70
	}
}

func (c *Classification) RecommendedAction(threshold int) string {
	if c == nil || c.Category == "safe" {
		return "none"
	}
	if c.Severity < threshold {
		return "warn"
	}
	return c.SuggestedAction
}

func (c *Client) ClassifyBatch(ctx context.Context, inputs []ClassifyInput) []*Classification {
	out := make([]*Classification, len(inputs))
	for i, in := range inputs {
		out[i] = c.ClassifyMessage(ctx, in)
	}
	return out
}
